{"n":43,"src":"read/guide/p43.jpg"},{"n":44,"src":"read/guide/p44.jpg"},{"n":45,"src":"read/guide/p45.jpg"},{"n":46,"src":"read/guide/p46.jpg"},{"n":47,"src":"read/guide/p47.jpg"},{"n":48,"src":"read/guide/p48.jpg"},{"n":49,"src":"read/guide/p49.jpg"},{"n":50,"src":"read/guide/p50.jpg"},{"n":51,"src":"read/guide/p51.jpg"},{"n":52,"src":"read/guide/p52.jpg"},{"n":53,"src":"read/guide/p53.jpg"},{"n":54,"src":"read/guide/p54.jpg"}],"sections":[{"id":"g1","title":"مدخل: وسائل اكتساب الخبرة","from":1,"to":5,"quiz":[{"q":"ما الذي تختلف فيه وسائل اكتساب الخبرة بحسب الدليل؟","o":["سرعة نقل الخبرة ومستوى الخبرة المنقولة","لون المواد المستخدمة","عدد الأشخاص في المنظمة فقط","اسم الجهة المضيفة"],"ans":0},{"q":"الزيارة الميدانية في هذا الدليل هي:","o":["وسيلة لاكتساب الخبرة من جهة أخرى","بديل عن كل أنواع التدريب","نشاط ترفيهي","إجراء مالي"],"ans":0}]},{"id":"g2","title":"الوحدة الأولى: الاستعداد للزيارة","from":6,"to":19,"quiz":[{"q":"أي من الصفات التالية يجب أن تتوفر في أهداف الزيارة؟","o":["واقعية ومحددة وواضحة وطموحة","عامة وغامضة","سرية فقط","طويلة جدًا"],"ans":0},{"q":"متى تُنفَّذ إجراءات الاستعداد؟","o":["قبل الشروع في الزيارة","بعد انتهاء الزيارة","أثناء الحوار فقط","لا حاجة لها"],"ans":0}]},{"id":"g3","title":"الوحدة الثانية: تنفيذ الزيارة","from":20,"to":29,"quiz":[{"q":"ما التصرف المناسب أثناء حديث الطرف الآخر؟","o":["الإنصات وتجنب المقاطعات غير المدروسة","المقاطعة المستمرة","الانشغال بالهاتف","إنهاء اللقاء مبكرًا"],"ans":0},{"q":"لماذا تُدوَّن الملحوظات أثناء الزيارة؟","o":["لحفظ الأفكار والمعلومات التي يُستفاد منها بعد الزيارة","لإضاعة الوقت","لأن الجهة تطلب ذلك فقط","لا فائدة منها"],"ans":0}]},{"id":"g4","title":"الوحدة الثالثة: ما بعد الزيارة","from":30,"to":35,"quiz":[{"q":"ما الحد المقترح للملخص التنفيذي في تقرير الزيارة؟","o":["ما لا يزيد عن صفحة","عشر صفحات","لا حد له","فقرة واحدة من سطر"],"ans":0},{"q":"أي مما يلي من مكوّنات خاتمة التقرير؟","o":["التوصيات والأسئلة العالقة","الدعاية للجهة","الفواتير","قائمة الحضور فقط"],"ans":0}]},{"id":"g5","title":"الوحدة الرابعة: النماذج المساعدة","from":36,"to":54,"quiz":[{"q":"عند المفاضلة بين الجهات المرشحة، كيف تُقيَّم كل جهة؟","o":["بدرجة من عشرة لكل معيار مع أوزان للمعايير","بالقرعة","بحسب الاسم","دون معايير"],"ans":0},{"q":"ما الغرض من نموذج خطاب طلب الموافقة على الزيارة؟","o":["تقديم صيغة قياسية لطلب الموافقة","تسجيل ملحوظات الحوار","حساب الميزانية","تقييم الأفكار"],"ans":0}]}],"addedAt":"2026-10-19"}',1,719,0,'2026-11-09T08:11:20.609Z','seed');
